UPDATE public.recipe_steps s SET text='將檸檬汁、蒜蓉、辣椒及糖拌勻成醬汁，備用。' FROM public.recipes r WHERE s.recipe_id=r.id AND r.slug='lemon-spicy-pan-fried-chicken' AND r.is_public AND s.step_no=2 AND s.text='將檸檬汁、蒜蓉、辣椒、剩餘生抽和糖拌勻，備用。';
GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'Step precondition changed: lemon-spicy-pan-fried-chicken 2'; END IF;
UPDATE public.recipe_steps s SET text='平底鑊加入食油1茶匙，中火加熱。' FROM public.recipes r WHERE s.recipe_id=r.id AND r.slug='herb-pan-fried-cod' AND r.is_public AND s.step_no=3 AND s.text='平底鑊加入 1 茶匙橄欖油，中火加熱。';
GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'Step precondition changed: herb-pan-fried-cod 3'; END IF;
END $audit$;
